### Frida Native Function Hooking via Interceptor.attach
Frida memungkinkan injeksi kode JavaScript ke proses native secara runtime untuk mencegat pemanggilan fungsi C/C++ pada pustaka bersama (.so, .dll, .dylib).

#### Implementasi Kode Hooking:
```javascript
// Hook fungsi native berdasarkan nama simbol atau offset biner
const targetModule = Process.getModuleByName("libtarget.so");
const targetFunc = targetModule.findExportByName("process_sensitive_buffer");

if (targetFunc) {
    Interceptor.attach(targetFunc, {
        onEnter: function (args) {
            console.log("[+] process_sensitive_buffer dipanggil!");
            const bufferPtr = args[0];
            const bufferLen = args[1].toInt32();

            console.log("[*] Buffer Pointer: " + bufferPtr);
            console.log("[*] Panjang Buffer: " + bufferLen + " bytes");

            // Cetak isi memori dalam format hexdump rapi
            if (bufferLen > 0 && bufferLen <= 1024) {
                console.log(hexdump(bufferPtr, {
                    offset: 0,
                    length: bufferLen,
                    header: true,
                    ansi: false
                }));
            }
        },
        onLeave: function (retval) {
            console.log("[+] Return value: " + retval.toInt32());
        }
    });
}
```

### Android SSL Pinning Verification via Frida Runtime
Dalam pengujian keamanan internal, verifikasi sertifikat TLS pada klien Android sering kali diinspeksi untuk memastikan bahwa pustaka HTTP (seperti OkHttp3 dan Java TrustManager) menangani validasi rantai sertifikat dengan benar.

#### Implementasi Frida Script:
```javascript
Java.perform(function () {
    console.log("[*] Mengaitkan runtime Java untuk audit TLS TrustManager...");

    // 1. Hook X509TrustManager standar Java
    const X509TrustManager = Java.use("javax.net.ssl.X509TrustManager");
    const TrustManagerImpl = Java.use("com.android.org.conscrypt.TrustManagerImpl");

    TrustManagerImpl.checkTrustedRecursive.implementation = function (
        certs, host, clientAuth, untrustedChain, trustAnchorChain, used
    ) {
        console.log("[+] Verifikasi sertifikat Conscrypt untuk host: " + host);
        return certs; // Pass audit chain untuk simulasi lab uji
    };

    // 2. Hook OkHttp3 CertificatePinner jika aplikasi menggunakan OkHttp
    try {
        const CertificatePinner = Java.use("okhttp3.CertificatePinner");
        CertificatePinner.check.overload("java.lang.String", "java.util.List").implementation = function (hostname, peerCertificates) {
            console.log("[+] OkHttp CertificatePinner bypass audit untuk: " + hostname);
        };
    } catch (e) {
        console.log("[-] OkHttp3 tidak ditemukan di classpath target.");
    }
});
```
